    tensor aph428 = ggml_concat(m, ggml_concat(m, ggml_concat(m, ggml_concat(m, ggml_concat(m, ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)0*pool406->nb[0]))), 0.25f), ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)3*pool406->nb[0]))), 0.25f), 0), ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)6*pool406->nb[0]))), 0.25f), 0), ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)10*pool406->nb[0]))), 0.25f), 0), ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)13*pool406->nb[0]))), 0.25f), 0), ggml_scale(m, ggml_sum_rows(m, ggml_cont(m, ggml_view_4d(m, pool406, 4, pool406->ne[1], pool406->ne[2], pool406->ne[3], pool406->nb[1], pool406->nb[2], pool406->nb[3], (size_t)16*pool406->nb[0]))), 0.25f), 0);
