FamBeit_params FamBeit_detect_params(model_file const& f) {
    FamBeit_params p{};
    // GGUF general.architecture 검증 (모델은 정적 unroll 이라 추가 하이퍼파라미터 없음).
    if (std::string_view arch = f.arch(); arch != "fambeit") {
        throw except(
            "Architecture expected to be 'fambeit', but was '{}' ({})",
            arch, f.path);
    }
    return p;
}

